import React, { useState } from "react";
import Modal from "../components/Modal";

export default function AdminEditProduct({ isOpen, onClose, product }) {
  const [form, setForm] = useState({
    name: product?.name || "",
    variation: product?.variation || "",
    price: product?.price || "",
    description: product?.description || "",
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <h2 className="text-2xl font-bold mb-4" style={{ color: "#000000" }}>
        Edit Product
      </h2>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-bold text-black">Product Name</label>
          <input
            name="name"
            type="text"
            value={form.name}
            onChange={handleChange}
            className="w-full p-2 mt-1 rounded border"
            style={{ backgroundColor: "#E1E1E1" }}
          />
        </div>

        <div>
          <label className="block text-sm font-bold text-black">Variation</label>
          <input
            name="variation"
            type="text"
            value={form.variation}
            onChange={handleChange}
            className="w-full p-2 mt-1 rounded border"
            style={{ backgroundColor: "#E1E1E1" }}
          />
        </div>

        <div>
          <label className="block text-sm font-bold text-black">Price</label>
          <input
            name="price"
            type="number"
            value={form.price}
            onChange={handleChange}
            className="w-full p-2 mt-1 rounded border"
            style={{ backgroundColor: "#E1E1E1" }}
          />
        </div>

        <div className="col-span-2">
          <label className="block text-sm font-bold text-black">Description</label>
          <textarea
            name="description"
            value={form.description}
            onChange={handleChange}
            className="w-full p-2 mt-1 rounded border h-24"
            style={{ backgroundColor: "#E1E1E1" }}
          />
        </div>
      </div>

      <button
        className="mt-6 w-full py-2 font-bold rounded"
        style={{ backgroundColor: "#FF7E0D", color: "white" }}
      >
        Update Product
      </button>
    </Modal>
  );
}
